 * Converts an exposure time in nanoseconds into a human-readable camera shutter speed string.
 * Examples: 33_333_333ns -> "1/30s", 1_000_000ns -> "1/1000s", 500_000_000ns -> "0.5s",
 * 2_000_000_000ns -> "2s".
 */
fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"

    // One second expressed in nanoseconds
    val oneSecondNs = 1_000_000_000L

    if (exposureTimeNs >= oneSecondNs) {
        // Whole or fractional seconds (e.g. "0.5s", "2s", "1.3s")
        val seconds = exposureTimeNs.toDouble() / oneSecondNs
        return if (exposureTimeNs % oneSecondNs == 0L) {
            "${exposureTimeNs / oneSecondNs}s"
        } else {
            val rounded = String.format("%.1f", seconds)
            // Trim a trailing ".0" (e.g. 1.0s -> handled above, but guard anyway)
            if (rounded.endsWith(".0")) "${rounded.dropLast(2)}s" else "${rounded}s"
        }
    }

    // Sub-second exposures shown as unit fractions (e.g. "1/30s")
    val denominator = (oneSecondNs.toDouble() / exposureTimeNs).roundToInt().coerceAtLeast(1)
    if (denominator == 1) {
        return "1s"
    }
    return "1/${denominator}s"
}

